uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float3x3 fromLayer;
uniform float time;
uniform float radius;
uniform float intensity;
float4 readInput(float2 uv){if(uv.x<0.0||uv.y<0.0||uv.x>1.0||uv.y>1.0)return float4(0.0);return float4(image.eval(uv * size));}
half4 main(float2 coord){float2 p=(coord / size);float4 c=readInput(p);float a=0.0;for(int i=0;i<8;i++){float r=float(i)*.7853981634;a=max(a,readInput(p+float2(cos(r),sin(r))*radius).a);}float edge=clamp((a-c.a)*intensity,0.0,1.0);return float4(float3(.15,.65,1.0)*edge+c.rgb*(1.0-edge),edge+c.a*(1.0-edge));}
